 # Format only the newly written reviewer submissions for readable word/number boundaries.
 # The original frozen 20-point finding is reused byte-exact and never rewritten.
 if i!=4 or kind!='independent-entire-core-absence-or-consistently-wrong-whole-work':
  answers=[re.sub(r'(?<=[a-zäöüß])(?=[A-ZÄÖÜ])|(?<=[A-Za-zÄÖÜäöüß])(?=\d)|(?<=\d)(?=[A-Za-zÄÖÜäöüß])',' ',s) for s in answers]
 raw=sum(sum(v) for v in marks);score=min(raw,14) if cap else raw
